impl Plan {
    /// How a run of `kind` with `agent` in the project at `project_dir`,
    /// whose spec and code are at `locations`, is put in a container, with
    /// the task's understanding file, if it has one.
    pub fn new(
        kind: RunKind,
        agent: Agent,
        project_dir: &Path,
        locations: &Locations,
        understanding: Option<&Path>,
        platform: Platform,
    ) -> Self {
        let data = project_dir.join(APP_DIR);
        let reference = project_dir.join(agent.directory()).join("reference");
        let config = project_dir.join(crate::project_directory::CONFIG_FILE_NAME);
        let fluency = crate::piton_fluency::file(project_dir);
        let suspense_fluency = crate::suspense_fluency::file(project_dir);
        let spec = locations.spec.clone();
        // A code location the config leaves out, or gives as the project
        // itself, is the whole project.
        let code = locations
            .code
            .clone()
            .unwrap_or_else(|| project_dir.to_path_buf());
        let rw = |host: PathBuf| Mount {
            host,
            writable: true,
        };
        let ro = |host: PathBuf| Mount {
            host,
            writable: false,
        };
        let mut mounts = Vec::new();
        match kind {
            RunKind::Spec => {
                mounts.extend(spec.clone().map(rw));
                mounts.push(rw(reference));
                // The build's manifest of the files it owns, so a build in
                // the container can write the reference: the project's own,
                // so the host's next build starts from what it wrote.
                mounts.push(rw(project_dir.join(".piton")));
                mounts.push(ro(fluency));
                mounts.push(ro(suspense_fluency.clone()));
                mounts.push(ro(config));
                mounts.extend(understanding.map(|file| rw(file.to_path_buf())));
            }
            // Both locations, read only: the spec's source so `piton slice`
            // can read it, nothing changed.
            RunKind::Question => {
                mounts.push(ro(code.clone()));
                mounts.extend(spec.clone().map(ro));
                mounts.push(ro(reference));
                mounts.push(ro(config));
                mounts.push(ro(suspense_fluency));
            }
        }
        // What a mount holds that the run must not see: the project's data
        // and its git directory. A question sees both locations, whichever
        // holds the other.
        let unseen = vec![data, project_dir.join(".git")];
        // A Spec run never sees the code: an empty scratch folder stands in
        // its place, for the build to place the shape's guidance in.
        // The harness directory is scratch too, the reference mounted in it,
        // so the build can write what else it writes there, as skills.
        let scratch = match kind {
            RunKind::Spec => vec![code, project_dir.join(agent.directory())],
            RunKind::Question => Vec::new(),
        };
        let hidden = unseen
            .into_iter()
            .filter(|unseen| {
                mounts
                    .iter()
                    .any(|mount| unseen.starts_with(&mount.host) && *unseen != mount.host)
            })
            .collect();
        // Parents first, so what they hold is mounted over them.
        mounts.sort_by_key(|mount| mount.host.components().count());
        Self {
            kind,
            agent,
            project_dir: project_dir.to_path_buf(),
            platform,
            mounts,
            hidden,
            scratch,
            sessions: Some(sessions_folder(project_dir, kind)),
            covered: Vec::new(),
        }
    }

    /// This plan with each of `files`, the files attached to the run's
    /// prompt, mounted read only on its own, at its path under the project,
    /// and nothing else of the folder they are in.
    pub fn with_files(mut self, files: &[PathBuf]) -> Self {
        for file in files {
            if !self.mounts.iter().any(|mount| mount.host == *file) {
                self.mounts.push(Mount {
                    host: file.clone(),
                    writable: false,
                });
            }
        }
        // Parents first, so what they hold is mounted over them.
        self.mounts.sort_by_key(|mount| mount.host.components().count());
        self
    }

    /// This plan, for a Spec run, as the project lets it read the code at
    /// `code`, or not: the code location mounted read only in place of its
    /// scratch folder, its guidance files alone covered by scratch, so the
    /// run can read the code but never change it. Every other mount, and
    /// what the run may write, is as it was.
    /// With `whole`, the project directory too, read only, beneath every
    /// other mount, but for its git directory and data, each hidden.
    pub fn reading_code(mut self, reads: bool, whole: bool, locations: &Locations) -> Self {
        if !reads || self.kind != RunKind::Spec {
            return self;
        }
        if whole && !self.mounts.iter().any(|mount| mount.host == self.project_dir) {
            self.mounts.push(Mount {
                host: self.project_dir.clone(),
                writable: false,
            });
        }
        let code = locations
            .code
            .clone()
            .unwrap_or_else(|| self.project_dir.clone());
        self.scratch.retain(|scratch| *scratch != code);
        self.mounts.push(Mount {
            host: code.clone(),
            writable: false,
        });
        let data = self.project_dir.join(APP_DIR);
        let spec = locations.spec.clone();
        // What the spec location holds is its own, written as ever.
        self.covered = guidance_files(&code)
            .into_iter()
            .filter(|file| spec.as_ref().is_none_or(|spec| !file.starts_with(spec)))
            .filter(|file| !file.starts_with(&data))
            .map(|file| (file, None))
            .collect();
        // The project's data and git directory, which the code location or
        // the whole project may hold, are still left out.
        let widest = if whole { self.project_dir.clone() } else { code };

