const LEAST_ABI: i32 = 3;

/// The ABI scoping abstract Unix sockets and signals.
const SCOPED_ABI: i32 = 6;

/// The ABI covering connecting to Unix sockets by path.
const RESOLVE_UNIX_ABI: i32 = 9;

/// The ABI used, the kernel's, but no newer than this crate knows.
fn abi() -> (i32, ABI) {
    let version = kernel_abi();
    let known = version.min(9);
    (version, ABI::from(known))
}

pub fn status() -> Result<String, Refused> {
    let (version, _) = abi();
    if version == 0 {
        return Err(Refused {
            message: "this kernel has no Landlock, which the sandbox needs: it isn't built \
                      with it, or it isn't enabled at boot (add `landlock` to the `lsm=` \
                      kernel parameter)"
                .into(),
            details: "landlock_create_ruleset gave no ABI version".into(),
        });
    }
    if version < LEAST_ABI {
        return Err(Refused {
            message: format!(
                "this kernel's Landlock is ABI {version}, and the sandbox needs ABI {LEAST_ABI} \
                 or later, as Linux 6.2 gives"
            ),
            details: String::new(),
        });
    }
    let reach = if version >= RESOLVE_UNIX_ABI {
        "files and Unix sockets"
    } else if version >= SCOPED_ABI {
        "files and abstract Unix sockets; sockets by path are left out"
    } else {
        "files; Unix sockets are left out"
    };
    Ok(format!("Landlock ABI {version}: {reach}"))
}

pub fn enforce(command: &mut Command, compiled: &Compiled) -> Result<(), Refused> {
    status()?;
    let (version, abi) = abi();
    let failed = |err: landlock::RulesetError| Refused {
        message: "its Landlock ruleset couldn't be built".into(),
        details: err.to_string(),
    };
    let all = AccessFs::from_all(abi);
    let read = AccessFs::from_read(abi);
    let mut ruleset = Ruleset::default()
        .set_compatibility(CompatLevel::HardRequirement)
        .handle_access(all)
        .map_err(failed)?;
    if version >= SCOPED_ABI {
        ruleset = ruleset
            .scope(Scope::AbstractUnixSocket | Scope::Signal)
            .map_err(failed)?;
    }
    let mut created = ruleset.create().map_err(failed)?;
    for rule in &compiled.rules {
        let access = match rule.access {
            Access::ReadOnly => read,
            Access::ReadWrite => all,
        };
        // Opened now, as a descriptor: the grant is on what it is, never on
        // its name looked up again.
        for beneath in path_beneath_rules([&rule.path], access) {
            let beneath = beneath.map_err(failed)?;
            created = created.add_rule(beneath).map_err(|err| Refused {
                message: format!("{} couldn't be granted", rule.path.display()),
                details: err.to_string(),
            })?;
        }
    }
    let created = Mutex::new(Some(created));
    // In the child, after fork, before exec: nothing but syscalls.
    unsafe {
        command.pre_exec(move || {
            // Every descriptor but the standard three closed as it runs its
            // program, so none open on a denied file is inherited.
            libc::syscall(libc::SYS_close_range, 3u32, u32::MAX, libc::CLOSE_RANGE_CLOEXEC);
            let ruleset = created
                .lock()
                .ok()
                .and_then(|mut created| created.take())
                .ok_or_else(|| std::io::Error::other("the sandbox was applied twice"))?;
            let status = ruleset.restrict_self().map_err(std::io::Error::other)?;
            if status.ruleset != RulesetStatus::FullyEnforced || !status.no_new_privs {
                return Err(std::io::Error::other("the sandbox couldn't be fully enforced"));
            }
            Ok(())
        });
    }
    Ok(())
}

//! The macOS backend, as the SandboxScope says: Seatbelt. A sandbox profile
//! is generated from the policy, in the sandbox profile language, and the
//! run's program is started through `/usr/bin/sandbox-exec` with it, so it
//! is in force before the program runs and inherited by every process it
//! starts, with no administrator rights.
//!
//! `sandbox-exec` and its profile language are deprecated by Apple and
//! undocumented in parts; this backend is untested on a Mac at the time of
//! writing, as SANDBOX.md says.

use std::process::Command;

use super::{Access, Compiled, Refused};

const SANDBOX_EXEC: &str = "/usr/bin/sandbox-exec";

pub fn status() -> Result<String, Refused> {
    if std::path::Path::new(SANDBOX_EXEC).is_file() {
        Ok("Seatbelt: files and Unix sockets".into())
    } else {
        Err(Refused {
            message: format!("{SANDBOX_EXEC}, which the sandbox needs, isn't on this Mac"),
            details: String::new(),
        })
    }
}

/// A path as the profile language quotes it.
fn quoted(path: &std::path::Path) -> String {
    let text = path.to_string_lossy();
    format!("\"{}\"", text.replace('\\', "\\\\").replace('"', "\\\""))
}

/// The Seatbelt profile `compiled` gives: deny by default, allow reading,
/// or reading and writing, only the policy's paths and what any process
/// needs to run, and deny the denied paths outright.
pub fn profile(compiled: &Compiled) -> String {
    let mut out = String::from(
        "(version 1)\n\
         (deny default)\n\
         (allow process-exec process-fork process-info* signal (target same-sandbox))\n\
         (allow sysctl-read mach-lookup ipc-posix-shm* ipc-posix-sem iokit-open user-preference-read)\n\
         (allow network*)\n\
         (allow file-read-metadata)\n\
         (allow file-read* file-write* (literal \"/dev/null\") (literal \"/dev/tty\") (regex #\"^/dev/ttys[0-9]+$\") (literal \"/dev/dtracehelper\"))\n\
         (allow file-read* (literal \"/dev/random\") (literal \"/dev/urandom\") (literal \"/\"))\n",
    );
    for rule in &compiled.rules {
        let what = match rule.access {
            Access::ReadOnly => "file-read*",
            Access::ReadWrite => "file-read* file-write*",
        };
        out.push_str(&format!("(allow {what} (subpath {}))\n", quoted(&rule.path)));
    }
    // Last, so they win over any grant.
    for denied in &compiled.denied {
        out.push_str(&format!(
            "(deny file-read* file-write* (subpath {}))\n",
            quoted(denied)
        ));
    }
    out
}

pub fn enforce(command: &mut Command, compiled: &Compiled) -> Result<(), Refused> {
    status()?;
    let program = command.get_program().to_owned();
    let args: Vec<std::ffi::OsString> = command.get_args().map(ToOwned::to_owned).collect();
    let envs: Vec<(std::ffi::OsString, Option<std::ffi::OsString>)> = command
        .get_envs()
        .map(|(key, value)| (key.to_owned(), value.map(ToOwned::to_owned)))
        .collect();
    let dir = command.get_current_dir().map(ToOwned::to_owned);
    let mut wrapped = crate::process::command(SANDBOX_EXEC);
    wrapped.arg("-p").arg(profile(compiled)).arg(program).args(args);
    for (key, value) in envs {
        match value {
            Some(value) => wrapped.env(key, value),
            None => wrapped.env_remove(key),
        };
    }
    if let Some(dir) = dir {
        wrapped.current_dir(dir);
    }
    *command = wrapped;
    Ok(())
}

//! The Windows backend. The SandboxScope's backend is AppContainer, with
//! each run's paths granted to the container's identity in their access
//! lists and the run held in a job object. That backend isn't built yet,
//! so on Windows every run that needs a sandbox fails closed, saying so,
//! and is never started unrestricted, as SANDBOX.md says.

use std::process::Command;

use super::{Compiled, Refused};

fn not_built() -> Refused {
    Refused {
        message: "the Windows sandbox backend (AppContainer) isn't built yet, so no task or \
                  question can run on Windows; runs are never started unrestricted"
            .into(),
        details: format!("See {}", super::DOCUMENTATION),
    }
}

pub fn status() -> Result<String, Refused> {
    Err(not_built())
}

pub fn enforce(_: &mut Command, _: &Compiled) -> Result<(), Refused> {
    Err(not_built())
}

