pub enum Check {
    Git,
    Piton,
    Harness,
    Podman,
    PodmanMachine,
    Containers,
    HarnessLogin,
}

impl Check {
    /// The checks on `platform`, in order: the Podman machine only where
    /// Podman runs one.
    pub fn all(platform: Platform) -> Vec<Check> {
        [
            Check::Git,
            Check::Piton,
            Check::Harness,
            Check::Podman,
            Check::PodmanMachine,
            Check::Containers,
            Check::HarnessLogin,
        ]
        .into_iter()
        .filter(|check| *check != Check::PodmanMachine || platform.has_machine())
        .collect()
    }

    pub fn name(self) -> &'static str {
        match self {
            Check::Git => "Git",
            Check::Piton => "Piton",
            Check::Harness => "Harness",
            Check::Podman => "Container runtime",
            Check::PodmanMachine => "Runtime machine",
            Check::Containers => "Containers",
