    fn render_containers(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let muted = cx.theme().muted_foreground;
        let runtime = self.render_runtime(cx);
        let resources = self.render_resources(cx);
        let logins = v_flex()
            .gap_2()
            .children(Agent::RUNNABLE.into_iter().map(|agent| {
                let state = self
                    .containers
                    .as_ref()
                    .and_then(|containers| {
                        containers
                            .logins
                            .iter()
                            .find(|(known, _)| *known == agent)
                            .map(|(_, logged_in)| *logged_in)
                    })
                    .flatten();
                h_flex()
                    .gap_2()
                    .child(div().w(px(120.)).child(agent.label()))
                    .child(
                        div()
                            .w(px(120.))
                            .text_sm()
                            .text_color(muted)
                            .child(match state {
                                Some(true) => "Logged in",
                                Some(false) => "Not logged in",
                                None => "Unknown",
                            }),
                    )
                    .children(
                        self.containers
                            .as_ref()
                            .and_then(|containers| {
                                containers.notes.iter().find(|(known, _)| *known == agent)
                            })
