/// Runs a short set of the hostile checks the sandbox is tested with, in a
/// temporary project of its own, as the settings' Test sandbox does: each
/// check, and whether the system refused it. Blocking.
pub fn self_test() -> Result<Vec<(String, bool)>, Refused> {
    status()?;
    let dir = std::env::temp_dir().join(format!("suspense-sandbox-test-{}", std::process::id()));
    std::fs::remove_dir_all(&dir).ok();
    let made = (|| -> std::io::Result<()> {
        std::fs::create_dir_all(dir.join("src"))?;
        std::fs::create_dir_all(dir.join("spec"))?;
        std::fs::write(dir.join("src/main.rs"), "fn main() {}\\n")?;
        std::fs::write(dir.join("spec/index.pi"), "export secret: 1\\n")?;
        Classification {
            code_roots: vec!["src".into()],
            spec_roots: vec!["spec".into()],
            ..Classification::default()
        }
        .save(&dir)
    })();
    made.map_err(|err| Refused {
        message: "its temporary project couldn't be made".into(),
        details: err.to_string(),
    })?;
    let git = |args: &[&str]| {
        crate::process::command("git")
            .args(["-c", "user.name=Suspense", "-c", "user.email=suspense@localhost"])
            .args(args)
            .current_dir(&dir)
            .output()
            .ok();
    };
    git(&["init", "-q"]);
    git(&["add", "-A"]);
    git(&["commit", "-qm", "test"]);
    let agent = crate::agent::Agent::Claude;
    let checks: [(ProfileKind, &str, &str); 8] = [
        (ProfileKind::Code, "A Code run reads the spec", "cat spec/index.pi"),
        (ProfileKind::Code, "A Code run writes the spec", "echo x > spec/new.pi"),
        (ProfileKind::Code, "A Code run reads the spec through `..`", "cat src/../spec/index.pi"),
        (ProfileKind::Code, "A Code run's child of a child reads the spec", "sh -c 'sh -c \\"cat spec/index.pi\\"'"),
        (ProfileKind::Code, "A Code run shows the spec through git", "git show HEAD:spec/index.pi"),
        (ProfileKind::Code, "A Code run moves the spec into the code", "mv spec/index.pi src/stolen.pi"),
        (ProfileKind::Spec, "A Spec run reads the code", "cat src/main.rs"),
        (ProfileKind::Spec, "A Spec run writes the code", "echo x > src/new.rs"),
    ];
    let mut results = Vec::new();
    for (kind, label, script) in checks {
        let prepared = prepare(kind, agent, &dir, &RunFiles::default());
        let refused = match prepared {
            Ok(prepared) => {
                let mut command = crate::process::command("sh");
                command.args(["-c", script]).stdin(std::process::Stdio::null());
                match prepared.apply(&mut command) {
                    Ok(()) => !command.output().is_ok_and(|output| output.status.success()),
                    Err(_) => true,
                }
            }
            Err(_) => true,
        };
        results.push((label.to_string(), refused));
    }
    std::fs::remove_dir_all(&dir).ok();
    Ok(results)
}

