            let status = read.await;
            this.update(cx, |this, cx| {
                this.sandbox = Some(status);
                cx.notify();
            })
            .ok();
        });
    }

    /// Runs Test sandbox: a short set of the hostile checks, in a temporary
    /// project, each saying whether the system refused it.
    fn test_sandbox(&mut self, cx: &mut Context<Self>) {
        self.testing = true;
        let run = cx.background_spawn(async { crate::sandbox::self_test() });
        self._sandbox_test = cx.spawn(async move |this, cx| {
            let found = run.await;
            this.update(cx, |this, cx| {
                this.sandbox_test = Some(found);
                this.testing = false;
                cx.notify();
            })
            .ok();
        });
        cx.notify();
    }

    /// Changes the open project's classification by `change`, saved at once.
    fn classify(&mut self, change: impl FnOnce(&mut Classification), cx: &mut Context<Self>) {
        let Some(project_dir) = ProjectDirectory::get(cx) else {
            return;
        };
        let mut classification = Classification::load(&project_dir);
        change(&mut classification);
        self.classification_error = classification
            .save(&project_dir)
            .err()
            .map(|err| format!("{err}").into());
        cx.notify();
    }

    /// Adds code or spec roots, chosen with the folder browser.
    fn add_root(&mut self, spec: bool, window: &mut Window, cx: &mut Context<Self>) {
        let Some(project_dir) = ProjectDirectory::get(cx) else {
            return;
        };
        let picked = cx.prompt_for_paths(PathPromptOptions {
            files: true,
            directories: true,
            multiple: true,
            prompt: Some("Add".into()),
        });
        cx.spawn_in(window, async move |this, cx| {
            let Ok(Ok(Some(paths))) = picked.await else {
                return;
            };
            this.update(cx, |this, cx| {
                let roots: Vec<String> = paths
                    .iter()
                    .filter_map(|path| path.strip_prefix(&project_dir).ok())
                    .map(|path| path.to_string_lossy().replace('\\', "/"))
                    .collect();
                this.classify(
                    |classification| {
                        let list = if spec {
                            &mut classification.spec_roots
                        } else {
                            &mut classification.code_roots
                        };
                        for root in roots {
                            if !list.contains(&root) {
                                list.push(root);
                            }
                        }
                    },
                    cx,
                )
            })
            .ok();
        })
        .detach();
    }

    /// Adds the pattern typed as classing files as spec, or as code.
    fn add_pattern(&mut self, spec: bool, window: &mut Window, cx: &mut Context<Self>) {
        let pattern = self.pattern.read(cx).value().trim().to_string();
        if pattern.is_empty() {
            return;
        }
        if globset::Glob::new(&pattern).is_err() {
            self.classification_error = Some(format!("`{pattern}` isn't a pattern").into());
            cx.notify();
            return;
        }
        self.classify(
            |classification| {
                let list = if spec {
                    &mut classification.spec_patterns
                } else {
                    &mut classification.code_patterns
                };
                if !list.contains(&pattern) {
                    list.push(pattern.clone());
                }
            },
            cx,
        );
        self.pattern.update(cx, |input, cx| input.set_value("", window, cx));
    }

    /// A list of the classification's `items`, each with Remove.
    fn render_classed(
        &self,
        id: &'static str,
        title: &'static str,
        items: &[String],
        remove: fn(&mut Classification, &str),
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let muted = cx.theme().muted_foreground;
        v_flex()
            .gap_1()
            .child(div().text_sm().font_medium().child(title))
            .children(items.iter().enumerate().map(|(n, item)| {
                let item = item.clone();
                h_flex()
                    .gap_2()
                    .text_sm()
                    .child(div().flex_1().min_w_0().truncate().child(item.clone()))
                    .child(
                        Button::new(SharedString::from(format!("{id}-remove-{n}")))
                            .ghost()
                            .xsmall()
                            .label("Remove")
                            .on_click(cx.listener(move |this, _, _, cx| {
                                let item = item.clone();
                                this.classify(|classification| remove(classification, &item), cx)
                            })),
                    )
            }))
            .when(items.is_empty(), |list| {
                list.child(div().text_sm().text_color(muted).child("None"))
            })
            .into_any_element()
    }

