    /// sandbox can run here, what it leaves out, and for the open project,
    /// its classification, its Spec tasks' reading, its profiles, and Test
    /// sandbox.
    fn render_sandbox(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let muted = cx.theme().muted_foreground;
        let danger = cx.theme().danger;
        let backend = crate::sandbox::backend_name();
        let status: AnyElement = match &self.sandbox {
            None => div().text_color(muted).child("Checking the sandbox…").into_any_element(),
            Some(Ok(enforces)) => div().child(enforces.clone()).into_any_element(),
            Some(Err(why)) => v_flex()
                .gap_1()
                .child(div().text_color(danger).child(format!(
                    "{backend} can't run here: {}. No task or question will run until it can.",
                    why.message
                )))
                .child(
                    Button::new("settings-sandbox-docs")
                        .small()
                        .label("Sandbox documentation")
                        .on_click(|_, _, cx| cx.open_url(crate::sandbox::DOCUMENTATION)),
                )
                .into_any_element(),
        };
        let outside = div().text_sm().text_color(muted).child(
            "Outside the sandbox, and never claimed as protected: the network, through which a \
             run could fetch the project from where it is published; the harness's own service, \
             which holds what earlier conversations sent it; and the clipboard.",
        );
