        let mut profiles = None;
        if let Some(project_dir) = ProjectDirectory::get(cx) {
            let classification = Classification::load(&project_dir);
            let conflict = classification.conflict(&project_dir);
            classification_view = Some(
                v_flex()
                    .gap_3()
                    .child(div().font_semibold().child("Classification"))
                    .child(div().text_sm().text_color(muted).child(
                        "Which paths are code and which are spec, kept in .suspense/sandbox.json. \
                         A path classed as neither is denied to Code and Spec runs alike.",
                    ))
                    .child(self.render_classed("settings-code-roots", "Code roots", &classification.code_roots, |c, item| c.code_roots.retain(|root| root != item), cx))
                    .child(
