                            .small()
                            .label("Add code root")
                            .on_click(cx.listener(|this, _, window, cx| this.add_root(false, window, cx))),
                    )
                    .child(self.render_classed("settings-spec-roots", "Spec roots", &classification.spec_roots, |c, item| c.spec_roots.retain(|root| root != item), cx))
                    .child(
                        Button::new("settings-add-spec-root")
                            .small()
                            .label("Add spec root")
                            .on_click(cx.listener(|this, _, window, cx| this.add_root(true, window, cx))),
                    )
                    .child(self.render_classed("settings-code-patterns", "Code patterns", &classification.code_patterns, |c, item| c.code_patterns.retain(|pattern| pattern != item), cx))
                    .child(self.render_classed("settings-spec-patterns", "Spec patterns", &classification.spec_patterns, |c, item| c.spec_patterns.retain(|pattern| pattern != item), cx))
                    .child(
                        h_flex()
                            .gap_2()
                            .child(div().w(px(220.)).child(Input::new(&self.pattern).small()))
                            .child(
                                Button::new("settings-add-code-pattern")
                                    .small()
                                    .label("Add as code")
                                    .on_click(cx.listener(|this, _, window, cx| this.add_pattern(false, window, cx))),
                            )
                            .child(
                                Button::new("settings-add-spec-pattern")
                                    .small()
                                    .label("Add as spec")
                                    .on_click(cx.listener(|this, _, window, cx| this.add_pattern(true, window, cx))),
                            ),
                    )
                    .children(conflict.map(|why| div().text_sm().text_color(danger).child(why)))
                    .children(self.classification_error.clone().map(|why| div().text_sm().text_color(danger).child(why)))
                    .child(
                        Button::new("settings-reset-classification")
                            .small()
                            .label("Reset to project locations")
                            .on_click(cx.listener(|this, _, _, cx| {
                                let Some(project_dir) = ProjectDirectory::get(cx) else {
                                    return;
