                                this.classify(
                                    |classification| *classification = Classification::from_locations(&project_dir),
                                    cx,
                                )
                            })),
                    ),
            );
            let agent = crate::agent::of_project(Some(&project_dir));
            let mut list = v_flex().gap_3().child(div().font_semibold().child("Profiles"));
            for kind in ProfileKind::SHOWN {
                let open = self.profiles_open.contains(&kind);
                let body: AnyElement = match crate::sandbox::summary(kind, agent, &project_dir) {
                    Err(why) => div().text_sm().text_color(danger).child(why.message).into_any_element(),
                    Ok(summary) => {
                        let line = |label: &str, items: &[String]| {
                            div().text_sm().child(format!(
                                "{label}: {}",
                                if items.is_empty() { "nothing".to_string() } else { items.join(", ") }
                            ))
                        };
                        v_flex()
                            .gap_0p5()
                            .child(line("Read-only", &summary.read_only))
                            .child(line("Read-write", &summary.read_write))
                            .child(line("Denied", &summary.denied))
                            .child(
                                Button::new(SharedString::from(format!("settings-profile-outside-{}", kind.label())))
                                    .ghost()
                                    .xsmall()
                                    .label(format!(
                                        "{} paths outside the project{}",
                                        summary.outside.len(),
                                        if open { "" } else { " ›" }
                                    ))
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        if !this.profiles_open.remove(&kind) {
                                            this.profiles_open.insert(kind);
                                        }
                                        cx.notify();
                                    })),
                            )
                            .when(open, |body| {
                                body.children(summary.outside.iter().map(|path| {
                                    div().pl_4().text_xs().text_color(muted).child(path.clone())
                                }))
                            })
                            .into_any_element()
                    }
                };
                list = list.child(v_flex().gap_1().child(div().font_medium().child(kind.label())).child(body));
            }
            profiles = Some(list);
        }
        let test = v_flex()
            .gap_1()
            .child(
                Button::new("settings-test-sandbox")
                    .small()
                    .label("Test sandbox")
                    .loading(self.testing)
                    .disabled(self.testing)
                    .on_click(cx.listener(|this, _, _, cx| this.test_sandbox(cx))),
            )
            .children(self.sandbox_test.as_ref().map(|found| match found {
                Err(why) => div().text_sm().text_color(danger).child(why.message.clone()).into_any_element(),
